#+
# Name:
#     seviri_combine_ir_glm_vis_parallel.py
# Purpose:
#     This is a script to create the combined netCDF file for SEVIRI (Meteosat-09) data files in parallel.
#     It reads the single NetCDF file generated by the EUMETSAT Data Tailor (EPCT), applies
#     hardcoded Planck and Solar constants to convert counts to Brightness Temperatures and
#     Reflectances, calculates Solar Zenith Angles, and writes the standardized COMBINED file.
# Calling sequence:
#     import seviri_combine_ir_glm_vis_parallel
# Input:
#     None.
# Functions:
#     _get_seviri_projection_data        : Calculates and caches expensive Cartopy transform points
#     seviri_get_ir_bt_from_counts       : Converts SEVIRI digital counts to Brightness Temperature (K)
#     seviri_get_ref_from_counts         : Converts SEVIRI digital counts to Reflectance
#     seviri_combine_ir_glm_vis_parallel : Creates and writes netCDF file that combines IR and VIS data
# Output:
#     Combined ir_vis netCDF file. Also returns name and file path of combined netCDF file.
# Keywords:
#     infile               : String keyword specifying SEVIRI EPCT NetCDF filename and path
#     layered_dir          : String keyword specifying directory to send the combined layer netCDF file
#     satellite            : String keyword specifying satellite name. DEFAULT = 'Meteosat09'
#     rewrite_nc           : IF keyword set (True), rewrite the combined netCDF file. DEFAULT = False
#     append_nc            : IF keyword set (True), append the combined netCDF file. DEFAULT = True
#     no_write_vis         : IF keyword set, do not write the VIS data. DEFAULT = False
#     no_write_irdiff      : IF keyword set, do not write the 6.2 micron IR data. DEFAULT = False
#     no_write_dirtyirdiff : IF keyword set, do not write the 12.0 micron IR data. DEFAULT = False
#     xy_bounds            : ARRAY of floating point values giving the domain boundaries [x0, y0, x1, y1]
#     proj_cache           : Dictionary to cache projection file data so it is only computed once.
#     verbose              : BOOL keyword to specify whether or not to print verbose messages. DEFAULT = True
# Author and history:
#     John W. Cooney           2026-06-08. (Adapted for SEVIRI from MTG code. Parallel optimized w/ cache).
#-

#### Environment Setup ###
import numpy as np
from netCDF4 import Dataset
import netCDF4
import os
import time
import datetime
import warnings
import xarray as xr
import re
from suncalc import get_position
import cartopy.crs as ccrs
import dask

# Satpy Imports
from satpy import Scene

# Fix for "3 leaked semaphore objects" in multiprocessing
dask.config.set(scheduler='single-threaded')

import sys
sys.path.insert(1, os.path.dirname(__file__))
sys.path.insert(2, os.path.dirname(os.getcwd()))
from glm_gridder.dataScaler import DataScaler
from glm_gridder.glm_data_processing import get_lat_lon_subset_inds

# --- HARDCODED METEOSAT-09 (MSG-2) CALIBRATION CONSTANTS ---
C1 = 1.19104e-5                                                                                                                                # mW m-2 sr-1 (cm-1)-4
C2 = 1.43877                                                                                                                                   # K (cm-1)-1
SEVIRI_CONSTANTS = {
    'channel_5':  [1600.548, 0.9963, 2.185],                                                                                                   # WV 6.2
    'channel_9':  [931.700,  0.9983, 0.640],                                                                                                   # IR 10.8
    'channel_10': [836.445,  0.9988, 0.408]                                                                                                    # IR 12.0
}
SOLAR_IRRADIANCE_CH1 = 65.2296                                                                                                                 # Value for MSG-2 (Meteosat-9) in mW m-2 sr-1 (cm-1)-1

# --- MODULE LEVEL CACHE FOR CARTOPY TRANSFORMATIONS ---
_SEVIRI_PROJECTION_CACHE = {}                                                                                                                  # Cache for projection file arrays

def _get_seviri_projection_data(proj_file, xy_bounds, sat, no_write_vis, scan_mode, proj_cache, verbose):
    """
    Load SEVIRI projection file data and cache the result.
    Matches the optimized MTG logic.
    """
    cache_key = (proj_file, tuple(xy_bounds), sat, no_write_vis, scan_mode)

    if cache_key in proj_cache:
        return(proj_cache[cache_key])

    if verbose:
        print('Reading SEVIRI projection file from disk and caching result: ' + proj_file)
        
    with Dataset(proj_file, 'r') as scan_proj_dataset:
        if len(xy_bounds) > 0:
            result = get_lat_lon_subset_inds(
                scan_proj_dataset, xy_bounds, return_lats=True,
                satellite=sat, use_native_ir=no_write_vis,
                scan_mode=scan_mode, verbose=verbose
            )
        else:
            result = get_lat_lon_subset_inds(
                scan_proj_dataset, [], return_lats=True, verbose=verbose
            )

    # When xy_bounds are specified, pre-subset lat/lon arrays in memory
    if len(xy_bounds) > 0:
        x_inds, y_inds, proj_extent, og_shape, lat_arr, lon_arr = result
        x0, x1  = np.min(x_inds), np.max(x_inds)
        y0, y1  = np.min(y_inds), np.max(y_inds)
        lat_sub = np.array(lat_arr[x0:x1, y0:y1])
        lon_sub = np.array(lon_arr[x0:x1, y0:y1])
        result  = (x_inds, y_inds, proj_extent, og_shape, lat_sub, lon_sub)

    proj_cache[cache_key] = result
    return(result)
    
def seviri_get_ir_bt_from_rad(radiance, channel_name):
    """
    Converts SEVIRI Radiances to Brightness Temperature using EUMETSAT formulas.
    (EPCT NetCDF files already output Radiance, so linear count scaling is skipped).
    """

    radiance = np.asarray(radiance, dtype=float)                                                                                               #Ensure input is float
    radiance = np.where(radiance <= 0, np.nan, radiance)                                                                                       #Mask invalid radiances to avoid log/division errors

    nu_c, alpha, beta = SEVIRI_CONSTANTS[channel_name]                                                                                         #Load hardcoded constant coefficients specific to target channel

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=RuntimeWarning)
        nom   = nu_c * C2                                                                                                                      #Compute EUMETSAT brightness temp conversion numerator
        denom = alpha * np.log(1.0 + (C1 * (nu_c**3.0)) / radiance)                                                                            #Compute EUMETSAT brightness temp conversion denominator
        bt    = (nom / denom) - (beta / alpha)                                                                                                 #Final calculation for Brightness Temperature output

    return(bt)
    
    
def seviri_get_ref_from_rad(radiance, earth_sun_distance_au):
    """
    Converts SEVIRI Radiances to Reflectance for VIS 0.6 (channel_1).
    (EPCT NetCDF files already output Radiance, so linear count scaling is skipped).
    """

    radiance = np.asarray(radiance, dtype=float)                                                                                               #Ensure input is float
    radiance = np.where(radiance <= 0, np.nan, radiance)                                                                                       #Mask invalid radiances to avoid log/division errors

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=RuntimeWarning)
        ref_img = (radiance * np.pi * (earth_sun_distance_au**2)) / SOLAR_IRRADIANCE_CH1                                                       #Calculate true reflectance utilizing solar irradiance scaling

    return(ref_img)

def seviri_combine_ir_glm_vis_parallel(infile=None, layered_dir=None, satellite='Meteosat09',
                                       domain_sector='F', rewrite_nc=False, append_nc=True,
                                       no_write_vis=False, no_write_irdiff=False, no_write_dirtyirdiff=False,
                                       xy_bounds=[], proj_cache=None, verbose=True):

    if proj_cache is None:
        proj_cache = _SEVIRI_PROJECTION_CACHE                                                                                                  #Fallback to module level cache if dict is not supplied

    t00 = time.time()

    infile      = os.path.realpath(infile)                                                                                                     #Create link to real path so compatible with Mac
    layered_dir = os.path.realpath(layered_dir)                                                                                                #Create link to real path so compatible with Mac
    basename    = os.path.basename(infile)                                                                                                     #Extract basename to isolate filename structures

    # ------------------------------------------------------------------
    # Time Parsing: Handles .nc (Start/End) and .nat (End only)
    # ------------------------------------------------------------------
    clean_name = basename.replace('T', '').replace('Z', '')
    matches = re.findall(r'(\d{14})', clean_name)
    sat_clean = satellite.lower().replace('-', '').replace('_', '')
    
    is_rss = False
    if 'rss' in sat_clean or 'rapid' in sat_clean:
        is_rss = True
    elif sat_clean in ['meteosat09', 'meteosat9', 'msg2', 'msg02'] and (datetime.datetime.strptime(matches[0][:8], "%Y%m%d") >= datetime.datetime(2013, 4, 9) and datetime.datetime.strptime(matches[0][:8], "%Y%m%d") < datetime.datetime(2018, 3, 1)):
        is_rss = True
    elif sat_clean in ['meteosat10', 'meteosat10', 'msg3', 'msg03'] and (datetime.datetime.strptime(matches[0][:8], "%Y%m%d") >= datetime.datetime(2018, 3, 1)):
        is_rss = True
    
    if infile.endswith('.nc') and len(matches) >= 2:
        ds0 = datetime.datetime.strptime(matches[0], "%Y%m%d%H%M%S")
        de0 = datetime.datetime.strptime(matches[1], "%Y%m%d%H%M%S")
    elif infile.endswith('.nat') and len(matches) >= 1:
        de0 = datetime.datetime.strptime(matches[0], "%Y%m%d%H%M%S")
        if is_rss:
            ds0 = de0 - datetime.timedelta(minutes=4, seconds=43)
        else:
            ds0 = de0 - datetime.timedelta(minutes=12, seconds=29)
    else:
        ds0 = datetime.datetime.utcnow()
        if is_rss:
            de0 = ds0 + datetime.timedelta(minutes=4, seconds=43)
        else:
            de0 = ds0 + datetime.timedelta(minutes=12, seconds=29)
                    
    dc0 = ds0 + (de0 - ds0) / 2.0 

    out_nc = os.path.join(layered_dir, f'OR_SEVIRI_L15_F_COMBINED_s{ds0.strftime("%Y%j%H%M%S0")}_e{de0.strftime("%Y%j%H%M%S0")}_c{dc0.strftime("%Y%j%H%M%S0")}.nc')
    
    if (not os.path.isfile(out_nc) or rewrite_nc or append_nc):

        os.makedirs(os.path.dirname(out_nc), exist_ok=True)                                                                                    #Ensure directory framework exists before executing file generation

        Scaler = DataScaler(nbytes=4, signed=True)                                                                                             #Extract data scaling and offset ability for np.int32
    
        x_inds, y_inds = [], []
        proj_extent_new = []
        if infile.endswith('.nc'):
            is_iodc = False
            if 'iodc' in sat_clean:
                is_iodc = True
            elif sat_clean in ['meteosat08', 'meteosat8', 'msg1', 'msg01']:
                if ds0 >= datetime.datetime(2016, 10, 1) and ds0 < datetime.datetime(2022, 6, 1):
                    is_iodc = True
            elif sat_clean in ['meteosat09', 'meteosat9', 'msg2', 'msg02']:
                if ds0 >= datetime.datetime(2022, 6, 1):
                    is_iodc = True
            
            proj_dir = os.path.join(os.path.dirname(os.path.dirname(os.getcwd())), 'data', 'sat_projection_files')
            proj_prefix = "seviri_iodc" if is_iodc else "seviri"
            proj_file = os.path.join(proj_dir, f"{proj_prefix}_satellite_full_scan_projections.nc")
            if is_iodc:
                if len(xy_bounds) > 0:
                    if not os.path.exists(proj_file):
                        print(f'Satellite projection file for the specified indices not found: {proj_file}')
                        exit()
                    x_inds, y_inds, proj_extent_new, og_shape, lat_arr_proj, lon_arr_proj = _get_seviri_projection_data(
                        proj_file, xy_bounds, satellite.lower(), no_write_vis, 'full', proj_cache, verbose
                    )
                else:
                    if os.path.exists(proj_file):
                        x_inds, y_inds, proj_extent, og_shape, lat_arr_proj, lon_arr_proj = _get_seviri_projection_data(
                            proj_file, [], satellite.lower(), no_write_vis, 'full', proj_cache, verbose
                        )
                    else:
                        print(f"ERROR: Missing {proj_file}. Run run_create_seviri_satellite_projections_ncdf first.")
                        exit()
            else:
                print(f"ERROR: Missing projection file if not for IODC domain!!. Run run_create_seviri_satellite_projections_ncdf first.")
                exit()
                
        # ==================================================================
        # 1. READ DATA: FORK BASED ON FILE TYPE
        # ==================================================================
        if infile.endswith('.nat'):
            if verbose: print(f'Loading Native data using Satpy from: {infile}')
            
            scn = Scene(filenames=[infile], reader='seviri_l1b_native')
            load_list = ['IR_108']
            if not no_write_vis: load_list.append('VIS006')
            if not no_write_irdiff: load_list.append('WV_062')
            if not no_write_dirtyirdiff: load_list.append('IR_120')
            
            # Using Satpy's built-in orientation handler to force standard North-Up/West-Left!
            scn.load(load_list, upper_right_corner='NE')
            if len(xy_bounds) > 0:
                if verbose: print(f'Cropping Native data to domain: {xy_bounds}')
                scn = scn.crop(ll_bbox=(xy_bounds[0], xy_bounds[1], xy_bounds[2], xy_bounds[3]))

            bt = scn['IR_108'].values
            lon_arr, lat_arr = scn['IR_108'].area.get_lonlats()
            
            if not no_write_vis: vis_img = scn['VIS006'].values / 100.0
            if not no_write_irdiff: bt2 = scn['WV_062'].values - bt
            if not no_write_dirtyirdiff: bt3 = scn['IR_120'].values - bt
            
            # Projection attrs for Satpy NetCDF definitions
            proj_dict = scn['IR_108'].area.proj_dict
            semi_major = float(proj_dict.get('a', 6378137.0))
            semi_minor = float(proj_dict.get('b', 6356752.3142))
            inv_flat   = float(semi_major / (semi_major - semi_minor)) if semi_major != semi_minor else 0.0
            cen_lon    = float(proj_dict.get('lon_0', 0.0))
            sat_height = float(proj_dict.get('h', 35785831.0))
            sweep_axis = 'y'
            
            # Re-added the missing Satpy boundaries!
            x_lims = scn['IR_108'].area.area_extent
            bounds_str = f"{x_lims[0]},{x_lims[2]},{x_lims[1]},{x_lims[3]}"

        elif infile.endswith('.nc'):
            if verbose: print(f'Loading EPCT NetCDF data using Xarray from: {infile}')
            
            with xr.open_dataset(infile, decode_cf=False) as ds:
                # Projections
                x_1d = np.asarray(ds['x'].values, dtype=float)
                y_1d = np.asarray(ds['y'].values, dtype=float)
                proj_attrs = ds['geostationary'].attrs
                semi_major = float(proj_attrs.get('semi_major_axis', 6378137.0))
                inv_flat   = float(proj_attrs.get('inverse_flattening', 298.257222101))
                cen_lon    = float(proj_attrs.get('longitude_of_projection_origin', 45.5))
                sat_height = float(proj_attrs.get('perspective_point_height', 35785831.0))
                sweep_axis = proj_attrs.get('sweep_angle_axis', 'y')
                semi_minor = semi_major * (1.0 - (1.0 / inv_flat))
                
                # Apply Xarray boundaries
                x_units = str(ds['x'].attrs.get('units', '')).lower()
                y_units = str(ds['y'].attrs.get('units', '')).lower()
                if 'rad' in x_units: x_1d = x_1d * sat_height
                if 'rad' in y_units: y_1d = y_1d * sat_height
                bounds_str = f"{np.nanmin(x_1d)},{np.nanmax(x_1d)},{np.nanmin(y_1d)},{np.nanmax(y_1d)}"

                # Apply fast cached lat/lon extracted from _get_seviri_projection_data instead of Cartopy transforms
                lon_arr = lon_arr_proj
                lat_arr = lat_arr_proj

                # Data Arrays
                ir_counts = np.asarray(ds['channel_9'].values, dtype=float)[::-1, :]
                bt = seviri_get_ir_bt_from_rad(ir_counts, 'channel_9')

                if not no_write_vis:
                    vis_counts = np.asarray(ds['channel_1'].values, dtype=float)[::-1, :]
                    earth_sun_distance = 1.0 - 0.01672 * np.cos(np.radians(0.9856 * (ds0.timetuple().tm_yday - 4)))
                    vis_img = seviri_get_ref_from_rad(vis_counts, earth_sun_distance)

                if not no_write_irdiff:
                    ir_counts_62 = np.asarray(ds['channel_5'].values, dtype=float)[::-1, :]
                    bt_62 = seviri_get_ir_bt_from_rad(ir_counts_62, 'channel_5')
                    bt2 = bt_62 - bt

                if not no_write_dirtyirdiff:
                    ir_counts_12 = np.asarray(ds['channel_10'].values, dtype=float)[::-1, :]
                    bt_12 = seviri_get_ir_bt_from_rad(ir_counts_12, 'channel_10')
                    bt3 = bt_12 - bt
                    
        else:
            raise ValueError(f"Unsupported file format for {infile}. Must be .nat or .nc")

#         if verbose:
#             print('SEVIRI combined array shapes:')
#             print('  lon_arr:', lon_arr.shape)
#             print('  lat_arr:', lat_arr.shape)
#             print('  bt     :', bt.shape)

        # ------------------------------------------------------------------
        # 2. UNIVERSAL PROCESSING (Masking, Subsetting)
        # ------------------------------------------------------------------
        if infile.endswith('.nc') and len(xy_bounds) > 0:
            bt = bt[np.min(x_inds):np.max(x_inds), np.min(y_inds):np.max(y_inds)]
            
            if not no_write_vis:
                vis_img = vis_img[np.min(x_inds):np.max(x_inds), np.min(y_inds):np.max(y_inds)]
            if not no_write_irdiff:
                bt2 = bt2[np.min(x_inds):np.max(x_inds), np.min(y_inds):np.max(y_inds)]
            if not no_write_dirtyirdiff:
                bt3 = bt3[np.min(x_inds):np.max(x_inds), np.min(y_inds):np.max(y_inds)]
                
            if infile.endswith('.nat'):
                lon_arr = lon_arr[np.min(x_inds):np.max(x_inds), np.min(y_inds):np.max(y_inds)]
                lat_arr = lat_arr[np.min(x_inds):np.max(x_inds), np.min(y_inds):np.max(y_inds)]

        if verbose:
            print('Calculating solar zenith angle')

        with warnings.catch_warnings():
            warnings.simplefilter("ignore", category=RuntimeWarning)
            zen = np.radians(90.0) - get_position(
                ds0.replace(tzinfo=datetime.timezone.utc),
                lon_arr,
                lat_arr
            )['altitude']                                                                                                                       #Extract solar altitude position calculations

        # Mask invalid data logic
        rm_inds = ((bt < 163.0) | (~np.isfinite(bt)) | (bt > 500.0))

        if not no_write_irdiff:
            bt2 = np.asarray(bt2, dtype=float)
            bt2[rm_inds] = -500.0                                                                                                              #Mask out of bounds indices statically

        if not no_write_dirtyirdiff:
            bt3 = np.asarray(bt3, dtype=float)
            bt3[rm_inds] = 500.0                                                                                                               #Mask out of bounds indices statically

        bt = np.asarray(bt, dtype=float)
        bt[rm_inds] = np.nan                                                                                                                   #Convert remaining primary invalid targets to nan

        if not no_write_vis:
            vis_img = np.asarray(vis_img, dtype=float)
            vis_img = np.clip(vis_img, 0, 2)                                                                                                   #Trim overflow reflectance logic to absolute threshold bounds

        # ------------------------------------------------------------------
        # 3. WRITE NETCDF (Agnostic to Source)
        # ------------------------------------------------------------------
        if verbose: print('Writing combined output netCDF ' + out_nc)

        with Dataset(out_nc, 'w', format='NETCDF4') as f:                                                                                      #Initiate write parameters targeting output NETCDF structure

            f.createDimension('Y', lon_arr.shape[0])                                                                                           #Set native Y axis dimension bounds
            f.createDimension('X', lat_arr.shape[1])                                                                                           #Set native X axis dimension bounds
            f.createDimension('time', 1)                                                                                                       #Set native timeline bounds to 1

            var_lon = f.createVariable(
                'longitude', 'f4', ('Y', 'X',),
                zlib=True,
                least_significant_digit=3
            )                                                                                                                                  #Construct 2D float mapping tied to longitude properties
            var_lon.long_name     = 'longitude -180 to 180 degrees east'                                                                       #Standardize global identifier assignment
            var_lon.standard_name = 'longitude'                                                                                                #Standardize CF compliant name mapping
            var_lon.units         = 'degrees_east'                                                                                             #Standardize output array unit parameters
            var_lon[:, :]         = lon_arr                                                                                                    #Assign array block to NetCDF longitude element

            var_lat = f.createVariable(
                'latitude', 'f4', ('Y', 'X',),
                zlib=True,
                least_significant_digit=3
            )                                                                                                                                  #Construct 2D float mapping tied to latitude properties
            var_lat.long_name     = 'latitude -90 to 90 degrees north'                                                                         #Standardize global identifier assignment
            var_lat.standard_name = 'latitude'                                                                                                 #Standardize CF compliant name mapping
            var_lat.units         = 'degrees_north'                                                                                            #Standardize output array unit parameters
            var_lat[:, :]         = lat_arr                                                                                                    #Assign array block to NetCDF latitude element

            var_t = f.createVariable('time', np.float64, ('time',))                                                                            #Construct basic 1D timescale variable alignment
            var_t.long_name     = "UTC time at which the geometric metadata are calculated."                                                   #Standardize layout assignment
            var_t.standard_name = "time"                                                                                                       #Standardize CF compliant timescale parameter mapping
            var_t.units         = "seconds since 2000-01-01 00:00:00.0"                                                                        #Set precise timescale conversion logic natively generated
            var_t[:]            = netCDF4.date2num(ds0, var_t.units)                                                                           #Convert tracking arrays numerically into target baseline format

            image_projection = f.createVariable(
                'imager_projection',
                np.int32,
                zlib=True
            )                                                                                                                                  #Construct underlying NetCDF layout defining base Grid parameters

            image_projection.long_name                      = "SEVIRI geostationary projection"                                                #Set standard long name attribute
            image_projection.satellite_name                 = satellite                                                                        #Set explicit tracker bound to satellite configuration target
            image_projection.grid_mapping_name              = "geostationary"                                                                  #Standard grid_mapping_name
            image_projection.perspective_point_height       = sat_height                                                                       #Lock native satellite height perspective dynamically
            image_projection.semi_major_axis                = semi_major                                                                       #Lock parameter bounds defining global semimajor axis shape definition
            image_projection.semi_minor_axis                = float(semi_minor)                                                                #Calculate and lock native semiminor axis properties manually
            image_projection.inverse_flattening             = inv_flat                                                                         #Lock parameter mapping for reverse planet flattening variables
            image_projection.latitude_of_projection_origin  = 0.0                                                                              #Lock target latitude intersection manually
            image_projection.longitude_of_projection_origin = cen_lon                                                                          #Define absolute longitudinal target mapping parameters
            image_projection.sweep_angle_axis               = sweep_axis                                                                       #Set sweep layout targeting primary rotation axis parameters
            
            if infile.endswith('.nc') and len(xy_bounds) > 0:
                image_projection.bounds = str(proj_extent_new[0]) + ',' + str(proj_extent_new[1]) + ',' + str(proj_extent_new[2]) + ',' + str(proj_extent_new[3])
            else:
                image_projection.bounds = bounds_str
                
            image_projection.bounds_units = 'm'

            proj4_string = (
                f"+proj=geos +lon_0={cen_lon} +h={sat_height} "
                f"+sweep={sweep_axis} +a={semi_major} +b={semi_minor} "
                f"+rf={inv_flat} +ellps=GRS80"
            )

            # Global Attributes
            f.Conventions = 'CF-1.8'                                                                                                           #Write netCDF conventions attribute
            f.description = (
                "This file combines unscaled SEVIRI IR and VIS data into one NetCDF file. "
                "Latitude/longitude arrays are registered to the north-up channel arrays. "
                "No GLM data are included."
            )

            f.geospatial_lat_min = str(np.nanmin(lat_arr))                                                                                     #Write min latitude as global variable
            f.geospatial_lat_max = str(np.nanmax(lat_arr))                                                                                     #Write max latitude as global variable
            f.geospatial_lon_min = str(np.nanmin(lon_arr))                                                                                     #Write min longitude as global variable
            f.geospatial_lon_max = str(np.nanmax(lon_arr))                                                                                     #Write max longitude as global variable
            f.x_inds             = x_inds if len(x_inds) > 0 else [0, lat_arr.shape[1]]
            f.y_inds             = y_inds if len(y_inds) > 0 else [0, lon_arr.shape[0]]
            f.spatial_resolution = "3.0km at nadir"                                                                                            #Write satellite spatial resolution to the file
            f.proj4_string       = proj4_string                                                                                                #Assign global Cartopy projection parameter target layout

            var_ir = f.createVariable(
                'ir_brightness_temperature',
                np.int32,
                ('time', 'Y', 'X',),
                zlib=True,
                fill_value=Scaler._FillValue
            )
            var_ir.set_auto_maskandscale(False)
            var_ir.long_name     = 'Infrared Brightness Temperature Image'
            var_ir.standard_name = 'IR_brightness_temperature'
            var_ir.units         = 'kelvin'
            var_ir.coordinates   = 'longitude latitude time'

            data, scale_ir, offset_ir = Scaler.scaleData(bt)
            var_ir[0, :, :]     = data
            var_ir.add_offset   = offset_ir
            var_ir.scale_factor = scale_ir

            if not no_write_vis:
                var_vis = f.createVariable(
                    'visible_reflectance',
                    np.int32,
                    ('time', 'Y', 'X',),
                    zlib=True,
                    fill_value=Scaler._FillValue
                )
                var_vis.set_auto_maskandscale(False)
                var_vis.long_name     = 'Visible Reflectance'
                var_vis.standard_name = 'Visible_Reflectance'
                var_vis.units         = 'reflectance'
                var_vis.coordinates   = 'longitude latitude time'

                data, scale_vis, offset_vis = Scaler.scaleData(np.asarray(vis_img))
                var_vis[0, :, :]      = data
                var_vis.add_offset    = offset_vis
                var_vis.scale_factor  = scale_vis

                var_zen = f.createVariable(
                    'solar_zenith_angle',
                    np.int32,
                    ('time', 'Y', 'X',),
                    zlib=True,
                    fill_value=Scaler._FillValue,
                    least_significant_digit=2
                )
                var_zen.set_auto_maskandscale(False)
                var_zen.long_name     = 'Solar Zenith Angle'
                var_zen.standard_name = 'solar_zenith_angle'
                var_zen.units         = 'degrees'

                data, scale_zen, offset_zen = Scaler.scaleData(np.asarray(np.degrees(zen)))
                var_zen[0, :, :]      = data
                var_zen.add_offset    = offset_zen
                var_zen.scale_factor  = scale_zen

            if not no_write_irdiff:
                var_ir2 = f.createVariable(
                    'ir_brightness_temperature_diff',
                    np.int32,
                    ('time', 'Y', 'X',),
                    zlib=True,
                    fill_value=Scaler._FillValue,
                    least_significant_digit=4
                )
                var_ir2.set_auto_maskandscale(False)
                var_ir2.long_name     = '6.2 - 10.8 micron Infrared Brightness Temperature Difference Image'
                var_ir2.standard_name = 'IR_brightness_temperature_difference'
                var_ir2.units         = 'kelvin'
                var_ir2.coordinates   = 'longitude latitude time'

                data, scale_ir2, offset_ir2 = Scaler.scaleData(bt2)
                var_ir2[0, :, :]      = data
                var_ir2.add_offset    = offset_ir2
                var_ir2.scale_factor  = scale_ir2

            if not no_write_dirtyirdiff:
                var_ir3 = f.createVariable(
                    'dirtyir_brightness_temperature_diff',
                    np.int32,
                    ('time', 'Y', 'X',),
                    zlib=True,
                    fill_value=Scaler._FillValue,
                    least_significant_digit=4
                )
                var_ir3.set_auto_maskandscale(False)
                var_ir3.long_name     = '12.0 - 10.8 micron Dirty Infrared Brightness Temperature Difference Image'
                var_ir3.standard_name = 'Dirty_IR_brightness_temperature_difference'
                var_ir3.units         = 'kelvin'
                var_ir3.coordinates   = 'longitude latitude time'

                data, scale_ir3, offset_ir3 = Scaler.scaleData(bt3)
                var_ir3[0, :, :]      = data
                var_ir3.add_offset    = offset_ir3
                var_ir3.scale_factor  = scale_ir3

        shape_arr = lon_arr.shape[0]                                                                                                           #Maintain absolute native dimensional boundaries mapped natively to parameter returns

        if verbose:
            print('Time to write data combined netCDF file = ' + str(time.time() - t00) + 'sec')

    else:
        with Dataset(out_nc, 'r') as combined_data:
            shape_arr = len(combined_data.dimensions['Y'])                                                                                     #Read Y dimension size directly instead of loading the full longitude array if returning parameters

    return(out_nc, shape_arr)